/**
 * A pasted Drive link comes in all kinds of shapes depending on where the
 * admin copied it from (a folder listing's address bar, the "Share"
 * dialog, an /open?id= link, etc.) — several of those open the file's
 * *location* in Drive instead of previewing the file itself. Rewriting
 * to the canonical /file/d/<id>/view form always opens an inline preview
 * as long as sharing is "Anyone with the link." Non-Drive URLs (or a
 * link with no recognizable file ID) pass through unchanged.
 */
function normalizeDriveViewUrl_(url) {
  url = (url || '').trim();
  if (!url) return url;
  var match = url.match(/\/file\/d\/([-\w]{20,})/) || url.match(/[?&]id=([-\w]{20,})/);
  if (!match) return url;
  return 'https://drive.google.com/file/d/' + match[1] + '/view';
}

